def alternateSigns(nums):
    n = len(nums)
    out = []
    p = q = 0
    while p < n and nums[p] < 0:
        p += 1
    while q < n and nums[q] >= 0:
        q += 1
    take_pos = True
    while p < n and q < n:
        if take_pos:
            out.append(nums[p])
            p += 1
            while p < n and nums[p] < 0:
                p += 1
        else:
            out.append(nums[q])
            q += 1
            while q < n and nums[q] >= 0:
                q += 1
        take_pos = not take_pos
    while p < n:
        if nums[p] >= 0:
            out.append(nums[p])
        p += 1
    while q < n:
        if nums[q] < 0:
            out.append(nums[q])
        q += 1
    return out
